    info: `### Для чего используется
**Wells score для ТГВ (1997, mod. 2003)** — прикроватная клиническая оценка вероятности **тромбоза глубоких вен** до лабораторных/инструментальных исследований. Определяет нужно ли делать D-димер или идти сразу на УЗДС.

### Три- или двухуровневая модель
**Трёхуровневая (оригинал 1997)**:
| Баллы | Вероятность |
|---|---|
| ≤ 0 | Низкая (3 %) |
| 1–2 | Умеренная (17 %) |
| ≥ 3 | Высокая (53 %) |

**Двухуровневая (2003, современная)**:
| Баллы | Вероятность |
|---|---|
| < 2 | ТГВ маловероятен |
| ≥ 2 | ТГВ вероятен |

### Алгоритм (ACCP 2021, ESC 2019)
| Wells | Следующий шаг | Результат → тактика |
|---|---|---|
| ≥ 2 | УЗДС вен ноги (компрессионное) | Положительно → антикоагуляция; отрицательно → повтор через 5–7 дн или + D-димер |
| < 2 | D-димер (высокочувствительный) | Отрицательный → ТГВ исключён; положительный → УЗДС |

### D-димер — age-adjusted cutoff (возраст-скорректированный)
У пациентов > 50 лет пороговое значение зависит от возраста:

| Единицы измерения | Формула cutoff |
|---|---|
| FEU | возраст × 10 нг/мл |
| DDU | возраст × 5 нг/мл |

Повышает специфичность с сохранением NPV ~ 100 %.

### Когда D-димер не работает (ложноположительный)
| Ситуация | Причина |
|---|---|
| Беременность | Всегда повышен |
| Рак | Активация коагуляции |
| Постоперационный период (до 4 нед) | Заживление |
| ДВС | Активное потребление факторов |
| Сепсис | Системное воспаление |
| Возраст > 80 без коррекции | Физиологическое повышение |
| Стационарные пациенты | Множественные сопутствующие причины |

### Лечение подтверждённого ТГВ
**Выбор антикоагулянта (ACCP 2021)**:
| Ситуация | Препарат |
|---|---|
| Некомплицированный ТГВ | DOAC (апиксабан 10×2×7 дн → 5×2; ривароксабан 15×2×21 дн → 20×1) |
| Рак-ассоциированный ТГВ | DOAC или LMWH (эноксапарин 1 мг/кг × 2) |
| Беременность | LMWH |
| CrCl < 30 | LMWH или варфарин |
| Массивная ТЭЛА с шоком | Тромболизис + LMWH / UFH |

### Длительность антикоагуляции (ACCP)
| Характер ТГВ | Длительность |
|---|---|
| Провокированный (операция, иммобилизация) | 3 мес |
| Непровокированный | ≥ 3 мес, рассмотреть пожизненную терапию |
| Рак-ассоциированный | До излечения основного заболевания |

### ТЭЛА сопутствующая
~ 50 % пациентов с проксимальным ТГВ имеют бессимптомную ТЭЛА. При диагнозе ТГВ — КТ-ангио опционально если есть лёгочные симптомы.

### Ограничения Wells для ТГВ
| Ограничение | Детали |
|---|---|
| Субъективный пункт | «Альтернативный диагноз столь же вероятен» (−2 балла) |
| Низкая специфичность | У пожилых, стационарных, онкологических |
| ТГВ верхних конечностей | Не валидизирован — используйте Constans score |

### Дополнительные предикторы риска (не входят в Wells)
| Фактор риска | Детали |
|---|---|
| Возраст | > 60 |
| Беременность | + послеродовой период до 6 нед |
| Эстрогены | КОК, ЗГТ |
| Тромбофилии | Leiden, протромбин G20210A, антифосфолипидный |
| Длительный перелёт | > 4 часов |`,
