    info: `### Для чего используется
**NEWS2 (National Early Warning Score 2, RCP 2017)** — стандарт **раннего распознавания клинического ухудшения** у взрослых стационарных пациентов. Обязателен во всех NHS-больницах UK с 2017, широко принят в EU и части РФ.

### 7 параметров (каждый 0–3 балла)
| Параметр | 0 баллов |
|---|---|
| ЧДД | 12–20 |
| SpO₂ (шкала 1, без ХОБЛ) | ≥ 96 % |
| SpO₂ (шкала 2, целевая 88–92 при ХОБЛ) | 88–92 % |
| Кислородотерапия | Нет |
| Температура | 36,1–38,0 °C |
| САД | 111–219 |
| ЧСС | 51–90 |
| Сознание (ACVPU) | Alert |

### Шкалы SpO₂
**Scale 1** — для большинства пациентов (цель ≥ 94 %)
**Scale 2** — для **ХОБЛ и пациентов с хронической гиперкапнической дыхательной недостаточностью** (цель 88–92 %). Используется только по назначению врача.

### ACVPU — сознание
- **A**lert
- **C**onfusion (новая) — NEW!
- **V**oice responsive
- **P**ain responsive
- **U**nresponsive

C/V/P/U = **3 балла**. Alert = 0.

### Интерпретация и частота мониторинга
| NEWS2 | Риск | Частота наблюдения | Действия |
|---|---|---|---|
| 0 | Низкий | Каждые 12 ч | Плановая |
| 1–4 | Низко-средний | Каждые 4–6 ч | Оценка мед. сестры |
| **3 в одной категории** | Средний | Каждый 1 ч | Срочная оценка врача |
| 5–6 | Средний | Каждый 1 ч | Срочная оценка врача; возможна необходимость усиленной помощи |
| ≥ 7 | Высокий | Непрерывный | Экстренная бригада, перевод в ICU |

**Ключевой момент**: любая единичная цифра **3** = средний риск (не только общая сумма).

### Цели использования
- Раннее распознавание сепсиса
- Выявление клинического ухудшения за 8–12 ч до события
- Запуск Rapid Response Team / MET-call
- Снижение cardiac arrest вне ICU

### NEWS2 для сепсиса (Royal College 2017)
- NEWS2 ≥ 5 у пациента с подозрением на инфекцию → пакет **Sepsis Six** в первый час:
  1. Кислород (цель SpO₂ ≥ 94 %, у ХОБЛ 88–92 %)
  2. Гемокультуры
  3. Антибиотики в/в
  4. Инфузия кристаллоидов
  5. Лактат, Hb
  6. Мочеотделение (катетер, учёт)

### NEWS2 vs MEWS vs qSOFA
| Шкала | Использование |
|---|---|
| MEWS | Предшественник NEWS, устарел |
| **NEWS2** | Общий стационарный мониторинг |
| qSOFA | Только подозрение на сепсис |
| NEWS2 **чувствительнее** qSOFA для ранней идентификации ухудшения |

### Когда НЕ применять
- Беременные (используйте MEOWS — Modified Early Obstetric Warning)
- Дети (PEWS)
- Пациенты с терминальными заболеваниями в паллиативе
- Пациенты после ОЦХ в первые часы (шкала не отражает норму)

### Ограничения
- Не учитывает лабораторные (лактат, Hb, лейкоциты)
- Не валидирован для ICU
- У пациентов с хронической гипотензией (терминальная ХСН) может давать ложно высокий балл
- Культура использования требует обучения персонала`,
