    bands: [
      { min: 1, max: 2, label: 'I–II',  color: '#22C55E', description: 'Низкий периоперационный риск.' },
      { min: 3, max: 3, label: 'III',    color: '#F59E0B', description: 'Умеренный. Тщательная подготовка.' },
      { min: 4, max: 5, label: 'IV–V',   color: '#EF4444', description: 'Высокий риск. Только жизненные показания.' },
      { min: 6, max: 6, label: 'VI',     color: '#991B1B', description: 'Смерть мозга.' },
    ],
    reference: 'ASA 2020 update. Добавляется "E" для экстренных операций.',
    info: `### Для чего используется
**ASA Physical Status** — стандарт оценки **физического состояния пациента перед анестезией и операцией**. Универсальная шкала анестезиологов всего мира.

### Классы (ASA 2020)
| Класс | Описание | Пример |
|---|---|---|
| **I** | Здоровый пациент | Молодой, некурящий, без болезней |
| **II** | Лёгкое системное заболевание | Курение, контролируемая АГ, СД, BMI 30–40 |
| **III** | Тяжёлое системное заболевание | Диабет или АГ с осложнениями, ХОБЛ, морбидное ожирение |
| **IV** | Тяжёлое системное заболевание — постоянная угроза жизни | Недавний ИМ / инсульт, активная ишемия ЛЖ, тяжёлая ХПН на диализе |
| **V** | Моribund — не ожидает выжить без операции | Разрыв аневризмы аорты, массивная травма, черепно-мозговая с ВЧГ |
| **VI** | Констатированная смерть мозга — забор органов | Донор органов |

### Модификатор
**E** (Emergency) — добавляется при **экстренной** операции (≥ 15 мин задержки → угроза жизни/органа). Например: «ASA II E».

### Применение
| Ситуация | Использование |
|---|---|
| Предоперационная оценка | Стандартное документирование |
| Страхование / биллинг | Используется в США для возмещения |
| Риск смертности | Коррелирует с 30-дн. исходом |

### 30-дневная смертность (ориентировочно)
| Класс | Плановая | Экстренная |
|---|---|---|
| I–II | < 0,5 % | 1–5 % |
| III | 1–5 % | 5–10 % |
| IV | 5–25 % | 10–30 % |
| V | > 50 % | > 50 % |

### Ограничения
- Субъективная (межрейтерская вариабельность ≈ 20 %)
- Не учитывает возраст, сложность операции, опыт хирурга
- Для детальной стратификации риска используйте **RCRI, ACS NSQIP, POSSUM**`,
